-- ===== INSERTs: new long-form/short-form written questions =====
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('e550c7c7-9ef1-4b73-970c-4f26e1499071', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q13', 'LO2', 'mock_exam', 'long_answer', false, false, 5, 'You are project manager on a £3.5m core-banking API integration for a regional building society, delivered under a matrix structure — engineering and data staff are seconded from IT and are also expected to support business-as-usual work. The newly appointed sponsor, previously an operations director, has started attending your daily stand-ups and instructing developers directly, and has asked you to "just make the technical calls together" on the business case going forward.

Explain (a) two ways the sponsor''s responsibilities differ from the project manager''s across the business case and governance, and (b) one risk the sponsor''s current behaviour creates given the matrix structure this project operates under.', NULL, NULL, '(a) Business case: the sponsor owns and is accountable for the business case and its benefits; the project manager consults during its development and delivers outputs to achieve the benefits once it is approved — the sponsor should not be sharing ownership of the business case with the PM. Governance: the sponsor sits on the governance board and makes decisions at gates; the project manager plans, executes and reports progress against the plan, rather than directing delivery day to day. (b) Risk: because staff report to both their functional line manager and the project manager in a matrix structure, the sponsor instructing developers directly bypasses that balance of authority and the PM''s own reporting line, risking conflicting instructions, confused accountability, and weaker line-manager buy-in for future resourcing.', '1 mark per differing responsibility area correctly identified (business case, governance), up to 2. 1 mark per correct explanation of the sponsor''s vs PM''s role within that area, up to 2. 1 mark for a risk explicitly linked to the matrix structure''s dual reporting. Cap 5.', NULL, true, NULL, 1, 13, 2);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('fd527a0b-b381-4112-9867-eab4c3cd4e48', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q14', 'LO6', 'mock_exam', 'long_answer', false, false, 5, 'You are project manager on an eighteen-month flood-defence upgrade for a local authority, currently at the end of Phase 2 of a linear life cycle with a decision gate due next week. Separately, the sponsor wants to know when to check whether the £40m business case''s flood-risk-reduction benefits actually materialised, and the authority''s internal audit team has asked to run an independent check of contractor compliance next month.

Explain (a) which of the three named review types (decision gates, benefits reviews, audits) applies to each of the three situations described, and (b) one factor that would typically be reported on to support the decision at next week''s gate.', NULL, NULL, '(a) The gate next week is a decision gate: an event-driven review at the end of a linear phase, giving the sponsor and governance board the chance to confirm the project is still on track before authorising the next phase. Checking whether flood-risk-reduction benefits materialised is a benefits review, typically held by the sponsor 6–12 months after handover to confirm the business case benefits were achieved. The audit team''s compliance check is an audit: an independent assessment, carried out by personnel independent of the project, that increases stakeholder confidence that governance and processes are being followed. (b) One reporting factor: actual costs against forecast costs (or Earned Value), the factor most commonly used to demonstrate how a project is performing at a gate.', '1 mark per situation correctly matched to its review type, up to 3. 1 mark for a valid reporting factor for the gate review. 1 mark for a brief, correct justification of why that factor is relevant. Cap 5.', NULL, true, NULL, 1, 14, 2);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('656e773b-a2c4-473b-8065-57460b85c70e', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q15', 'LO7', 'mock_exam', 'long_answer', false, false, 5, 'You are project manager on a £6m data-centre migration for a national insurer. The Chief Risk Officer, who sits on the governance board, has said she will not approve the next £2m drawdown until she has independent confidence the migration''s risk controls are actually working — not just what your monthly status report says.

Explain (a) two benefits an assurance activity would give the governance board in this situation, and (b) one reason you would recommend an external review rather than relying only on your internal PMO''s compliance checks.', NULL, NULL, '(a) Two benefits: assurance gives the board an objective view of how the migration is genuinely performing, independent of the project team''s own reporting, directly answering the CRO''s concern; it also supports the board''s decision-making on the £2m drawdown by validating the data behind the request, increasing the probability the release of funds is well-founded. (b) One reason: to ensure the assurance is genuinely independent and not influenced by the project team or by the organisation''s own concerns about how the migration is perceived — the CRO has specifically asked for confidence beyond internal reporting, and an external reviewer with no stake in the project can supply that independence.', '1 mark per distinct benefit of assurance to the board, up to 2. 1 mark per benefit explicitly linked to confidence or decision-support (not simply repeated), up to 2. 1 mark for a valid reason favouring external over internal-only review. Cap 5.', NULL, true, NULL, 1, 15, 2);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('8adccc75-d21b-4d33-b962-371468a0848c', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q16', 'LO11', 'mock_exam', 'long_answer', false, false, 5, 'You are project manager on a merger integration between two regional airlines. The Head of Flight Operations (protecting established safety procedures, resistant to change) and the newly hired Head of Customer Experience (pushing for a fast rebrand to capture market share) have clashed in three consecutive steering meetings, and the steering group chair has asked you to resolve it before the next meeting in one week.

Using the Thomas Kilmann model, explain (a) which conflict mode best describes each Head''s current behaviour, (b) which mode you would aim to steer the conflict towards and why, and (c) one practical action you would take given the one-week deadline.', NULL, NULL, '(a) The Head of Flight Operations is showing Avoid or Compete behaviour (low or high assertiveness, low cooperativeness), resisting change without engaging with the rebrand''s rationale. The Head of Customer Experience is showing Compete (high assertiveness, low cooperativeness), pushing their position without accommodating safety concerns. (b) Ideally Collaborate, since both goals — protecting safety standards and capturing market share — are legitimate and the relationship between the two roles needs to last well beyond this merger; but with only one week available, Compromise is the realistic fallback if a fully collaborative solution can''t be reached in time. (c) Facilitate a joint session where each Head states their underlying need rather than their position (why the rebrand pace matters; what specifically about it risks safety procedures), so a middle-ground option — such as a phased rebrand that leaves safety-critical materials untouched first — can be found within the week.', '1 mark per Head''s current behaviour correctly identified as a TKI mode, up to 2. 1 mark for a valid target mode named with justification. 1 mark for correctly linking the one-week deadline to mode choice (e.g. Compromise as fallback). 1 mark for one practical, time-bound facilitation action. Cap 5.', NULL, true, NULL, 1, 16, 2);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('c5f6be32-0256-4e1b-b886-65936d51643a', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q17', 'LO15', 'mock_exam', 'long_answer', false, false, 5, 'You are project manager on a housing-association fire-safety remediation programme. Nine months in, new government fire-safety regulation is published, tightening cladding inspection requirements. Your organisation''s risk team is two people covering the whole portfolio, and your sponsor has asked how the project will respond and how you personally will keep your own knowledge current given how fast this area is changing.

Explain (a) two project processes the new regulation is likely to influence and why, and (b) how you would apply the CPD cycle to keep your own knowledge of fire-safety regulation current.', NULL, NULL, '(a) Risk management, because the new regulation should be logged on the risk register and its impact on scope, time and cost assessed; and quality planning, because inspection acceptance criteria and assurance arrangements need updating to reflect the tightened cladding requirements. Change control may also be triggered if remediation scope needs to expand to comply. (b) CPD cycle: Reflection on practice — recognise that fire-safety regulation knowledge needs refreshing given the pace of change; Planning — identify how to close the gap, e.g. a regulatory-update course or engaging a fire-safety specialist; Action — complete the learning, such as attending a briefing from the regulator or a professional body; Evaluation — assess what was learned and how it changes the project''s approach, feeding back into future reflection.', '1 mark per project process correctly identified with a valid reason, up to 2. 1 mark per correctly named CPD cycle step applied to the scenario, up to 3 (any three of the four steps). Cap 5.', NULL, true, NULL, 1, 17, 2);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('f0960402-a67c-4f8e-b2ab-fa14cc925fc0', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q18', 'LO10', 'mock_exam', 'short_answer', false, false, 2, 'State two factors that can negatively affect communication on a project.', NULL, NULL, 'Any two of: poorly defined roles and responsibilities; language or cultural misunderstandings; personality clashes; a busy or distracting environment; unstable or unreliable technology for virtual communication; misalignment between verbal and non-verbal signals; overuse of technical or business jargon; high stress or workload.', '1 mark per valid distinct negative factor, up to 2. Cap 2.', NULL, true, NULL, 1, 18, 2);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('8b742ce2-bdfa-4ccd-b5cc-74b3e5ae8ad8', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q19', 'LO22', 'mock_exam', 'short_answer', false, false, 2, 'A project cost is described as "variable" and "indirect." State what each of these terms means.', NULL, NULL, 'Variable cost: a cost that changes in proportion to the level of resource consumed or output produced (e.g. materials per unit). Indirect cost: a cost that cannot be directly attributed to a specific project output and instead relates to running the wider organisation (e.g. a share of head-office overhead).', '1 mark for a correct definition of variable cost. 1 mark for a correct definition of indirect cost. Cap 2.', NULL, true, NULL, 1, 19, 2);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('450286a9-94a7-4987-8d35-bb159faa9173', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q20', 'LO12', 'mock_exam', 'short_answer', false, false, 2, 'State the leadership style best suited to (a) an emergency requiring an immediate decision, and (b) an experienced, high-performing team that needs little oversight.', NULL, NULL, '(a) Autocratic (directive) style — the leader makes the decision with limited team input, appropriate when speed and clarity matter most. (b) Delegative (laissez-faire) style — decision-making authority is largely handed to the team, appropriate when the team is established and capable of self-direction.', '1 mark for correctly naming autocratic for the emergency. 1 mark for correctly naming delegative for the established team. Cap 2.', NULL, true, NULL, 1, 20, 2);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('b200d2b0-dce2-479c-8484-e9f7ede02d28', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q33', 'LO16', 'mock_exam', 'long_answer', false, false, 5, 'You are project manager on a new patient-appointment booking system for an NHS trust. Fifty-five requirements have been gathered from clinicians, admin staff and patients, but the trust can only fund delivery of about two-thirds of them in this phase. The finance director wants confidence that the requirements being cut won''t damage patient safety.

Explain (a) the technique you would use to prioritise the fifty-five requirements and how it works, and (b) how configuration management would help protect the agreed scope once requirements are baselined.', NULL, NULL, '(a) MoSCoW: classify each requirement as Must have (non-negotiable, e.g. patient-safety-critical checks), Should have (high priority but the system survives without it short-term), Could have (desirable if time and budget allow) or Won''t have (explicitly out of scope this phase). Anchoring priority to patient safety and benefit value, not stakeholder pressure, directly answers the finance director''s concern, since Must-haves would only be reduced as a genuine last resort. (b) Configuration management protects the baseline through five activities: Planning (defining process and responsibilities), Identification (giving each system component a unique reference), Control (ensuring changes to items and their dependencies are managed formally), Status Accounting (tracking each item''s version through an audit trail), and Verification Audit (confirming delivered components conform to what was baselined) — together these stop scope drifting from the agreed, prioritised requirements.', '1 mark for correctly naming MoSCoW with a description of at least two categories. 1 mark for linking prioritisation to benefit/safety value rather than stakeholder pressure. 1 mark per configuration management activity correctly named, up to 3. Cap 5.', NULL, true, NULL, 2, 13, 2);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('ec2ba8d0-ee98-4e8b-a0f2-7ab67337ccdc', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q34', 'LO17', 'mock_exam', 'long_answer', false, false, 5, 'You are project manager on a new self-service kiosk for a mid-sized supermarket chain. A competitor launched a similar kiosk two months ago, so the board wants speed. Thirty requirements are on the table, and the product owner wants real customer usage data before committing to the full feature set.

Explain (a) the prioritisation technique you would use for the thirty requirements, (b) which life cycle approach best fits this situation and why, and (c) what the first release should be called and what it should contain.', NULL, NULL, '(a) MoSCoW: classify the thirty requirements as Must, Should, Could or Won''t have, anchoring priority to value delivered to the customer rather than internal pressure to match the competitor. (b) Iterative life cycle, because there is pressure for speed, requirements can evolve as real usage data comes in, and the product owner explicitly wants feedback before further investment — a linear approach would lock in the full feature set too early. (c) The first release should be a Minimum Viable Product (MVP): the smallest set of Must-have features (e.g. core payment and scan functions) needed to let real customers use the kiosk and generate feedback, before the chain invests further towards a Minimum Marketable Product with the full commercially viable feature set.', '1 mark for correctly naming MoSCoW. 1 mark for correctly recommending iterative with a valid reason. 1 mark for correctly naming MVP. 1 mark for correctly describing what MVP contains (Must-haves only, for feedback). 1 mark for correctly distinguishing MVP from MMP. Cap 5.', NULL, true, NULL, 2, 14, 2);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('f884b176-4ddf-4ac8-8a70-47b5070d242a', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q35', 'LO18', 'mock_exam', 'long_answer', false, false, 5, 'You are project manager on a pharmaceutical packaging-line upgrade. A batch of newly installed sealing equipment has just failed an on-site output test against the specified seal-strength requirement. The quality plan agreed sampling frequency, pass/fail criteria and supplier certificate checks at the outset. Your sponsor wants to know whether this is a one-off fault or a sign the supplier''s own processes are the problem.

Explain (a) the purpose of the quality plan in this situation, (b) two elements the quality plan should have defined before this test happened, and (c) the difference between the Quality Control check that has just failed and the Quality Assurance activity that would answer the sponsor''s question about the supplier''s processes.', NULL, NULL, '(a) The quality plan sets out how quality will be verified against requirements, defining what "good" looks like so a failed test like this has a clear, pre-agreed pass/fail basis rather than a dispute after the fact. (b) Two elements: pass/fail criteria for the seal-strength test (so the failure is unambiguous), and the frequency of testing (so it''s clear whether this was the first sample or a pattern). (c) Quality Control is the sealing-equipment output test itself: inspection/testing of the physical output against acceptance criteria, performed as part of the project team''s work, giving a binary pass/fail — which is what has just happened. Quality Assurance would independently audit whether the supplier''s own manufacturing and quality processes were actually followed, which is what would tell the sponsor whether this is an isolated fault or a wider process problem at the supplier.', '1 mark for a valid statement of the quality plan''s purpose. 1 mark per quality plan element correctly identified, up to 2. 1 mark for correctly distinguishing QC as output-focused. 1 mark for correctly distinguishing QA as process-focused and independent. Cap 5.', NULL, true, NULL, 2, 15, 2);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('e848f1f4-d979-4909-aab0-450ef79e3cf1', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q36', 'LO19', 'mock_exam', 'long_answer', false, false, 5, 'You are project manager on a £4m schools broadband-upgrade programme spanning IT infrastructure, staff training and cyber-security workstreams. The programme sponsor, a local authority director, has asked for a single document the education committee can use to get confidence the programme is properly set up — but two workstream leads think this level of planning is slowing them down and the team should "just get on with it."

Explain (a) four elements you would include in the integrated project management plan and why each matters for this programme, and (b) one reason producing this plan supports the programme''s success despite the workstream leads'' objection.', NULL, NULL, '(a) Scope, including a breakdown of deliverables and acceptance criteria across the three workstreams so "done" is unambiguous for infrastructure, training and cyber-security alike; Resources, showing roles, responsibilities and reporting lines across workstreams so accountability is clear; Cost, allocating the £4m across workstreams and over time so overspend in one area is visible early; Management, covering risk, quality and change-control strategies that hold the three workstreams together as one coherent programme rather than three disconnected projects. (b) The plan acts as a single source of truth, so the education committee, the three workstream leads and delivery partners are all working from the same agreed brief — reducing the very kind of misalignment and rework that "just getting on with it" would otherwise risk.', '1 mark per PMP element correctly named with a reason relevant to the scenario, up to 4. 1 mark for a valid, scenario-linked reason the PMP supports success. Cap 5.', NULL, true, NULL, 2, 16, 2);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('a18bf2f1-888d-4cbf-8bdc-39a721653315', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q37', 'LO21', 'mock_exam', 'long_answer', false, false, 5, 'You are project manager on a large solar-farm construction project. A national skills shortage in electrical installation has caused several sub-contractors to over-commit their crews across multiple sites. The project sponsor has said the grid-connection deadline is fixed and cannot move, but is willing to spend more to protect it.

Explain (a) which resource optimisation technique you would apply and why, (b) two practical actions you would take, and (c) one situation in which this technique alone would not be enough to protect the deadline.', NULL, NULL, '(a) Resource smoothing, because the sponsor has explicitly protected the end date over cost — smoothing answers "what resources do I need to deliver the work within the fixed timescale?" rather than letting the date slip. (b) Two actions: bring in additional electrical crews or sub-contractors to reduce task durations on the critical path; and parallelise non-dependent activities (e.g. panel mounting and inverter installation) that the original schedule had running sequentially, spreading resource demand more evenly. (c) One limiting situation: if qualified electrical installers are genuinely unavailable in the labour market regardless of price — a true skills shortage, not just a cost constraint — no amount of smoothing can manufacture capacity that doesn''t exist, and the project would need to explore levelling, scope reduction, or accept schedule risk against the connection window.', '1 mark for correctly naming resource smoothing with a valid reason linked to the fixed deadline. 1 mark per practical smoothing action correctly described, up to 2. 1 mark for a valid limiting scenario where smoothing is insufficient. 1 mark for correctly linking that limitation to genuine resource scarcity, not just cost. Cap 5.', NULL, true, NULL, 2, 17, 2);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('1c761f8f-be4c-4f3c-888d-f439151c8f2a', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q38', 'LO4', 'mock_exam', 'short_answer', false, false, 2, 'State two of the six PESTLE categories, and give one example of what each covers.', NULL, NULL, 'Any two of: Political (e.g. government stance, internal politics); Economic (e.g. market conditions, funding climate); Sociological (e.g. societal trends, demographics); Technological (e.g. emerging technology, obsolescence risk); Legal (e.g. employment law, regulatory compliance); Environmental (e.g. sustainability obligations, environmental impact).', '1 mark per correctly named PESTLE category with a valid example, up to 2. Cap 2.', NULL, true, NULL, 2, 18, 2);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('d71ea302-d8fc-4d3f-9edf-4f0f1895208d', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q39', 'LO8', 'mock_exam', 'short_answer', false, false, 2, 'A new system has just gone live. State the four stages of progressive implementation a user typically moves through as they adopt it.', NULL, NULL, 'Launch (what''s this?), Experimentation (I tried it once), Practising (I sometimes use it), Embedded (it''s how we do things here).', '1 mark for naming at least two of the four stages correctly. 1 mark for naming all four stages correctly, roughly in order. Cap 2.', NULL, true, NULL, 2, 19, 2);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('ba7ab240-7cf0-42fe-a7c8-8ae875a338cb', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q40', 'LO23', 'mock_exam', 'short_answer', false, false, 2, 'State two of the four typical proactive responses to a risk that is a threat.', NULL, NULL, 'Any two of: Avoid (eliminate the threat or its impact entirely, e.g. changing approach to remove the risk); Reduce/Mitigate (take action to lower the probability or impact); Transfer (pass the financial or other consequence to a third party, e.g. via insurance or contract); Accept (take no action, but retain contingency to manage the impact if it occurs).', '1 mark per valid, distinct threat response correctly named, up to 2. Cap 2.', NULL, true, NULL, 2, 20, 2);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('46640ade-ea7b-4a00-b8c0-f8dee44d1511', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q13', 'LO1', 'mock_exam', 'long_answer', false, false, 5, 'You are project manager on an ERP replacement for a mid-sized manufacturer. The finance module''s requirements are fully defined by fixed accounting and regulatory rules. A separate custom analytics dashboard has requirements that are expected to evolve significantly as users see early versions and provide feedback.

Explain (a) which life cycle you would recommend overall and why, (b) two reasons a purely linear life cycle would not suit the analytics dashboard workstream, and (c) one reason a purely iterative life cycle would not suit the finance module workstream.', NULL, NULL, '(a) A hybrid life cycle, combining linear and iterative approaches as appropriate to the work, because the two workstreams have genuinely different characteristics — one stable and rule-driven, one evolving — and applying a single life cycle to both would be poorly matched to at least one of them. (b) Two reasons: (1) the dashboard''s requirements are expected to evolve as user feedback comes in, but a linear life cycle assumes reasonably complete knowledge upfront with scope reviewed and fixed at predefined milestones; (2) linear offers less flexibility to incorporate change once a phase''s outputs are reviewed, which would force the dashboard''s design to be frozen before real user feedback is available. (c) One reason: the finance module''s requirements are fixed by accounting and regulatory rules that are already known, so applying an iterative life cycle — suited to uncertainty and evolving scope — would introduce unnecessary duration and cost uncertainty and make the business case harder to justify for something already well understood.', '1 mark for correctly recommending hybrid. 1 mark for a valid overall reason it fits both workstreams. 1 mark per valid reason linear does not suit the dashboard, up to 2. 1 mark for a valid reason iterative does not suit the finance module. Cap 5.', NULL, true, NULL, 1, 13, 3);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('2efe4132-5993-4a75-bffd-bb842fdf74e4', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q14', 'LO3', 'mock_exam', 'long_answer', false, false, 5, 'You are project manager on a new data centre for a cloud provider, built in a former industrial area with high youth unemployment. The facility consumes significant energy and water for cooling. The regional council has offered planning fast-track status in exchange for local job commitments.

Explain (a) two of the four sustainability elements most relevant to this project, with one scenario-specific consideration for each, and (b) two potential impacts on the project if sustainability is not built in from concept.', NULL, NULL, '(a) Environmental: energy and water efficiency of the cooling systems, given the scale of resource consumption a data centre requires and its contribution to climate impact. Social: community impact and equity, given the council''s job-commitment condition and the area''s high youth unemployment — local employment and training access is a direct social consideration here. (Economic — affordability and exposure to energy price volatility — or Administrative — health and safety and resource-efficiency regulation for cooling systems — could also be credited if justified.) (b) Two impacts: (1) breaching environmental legislation on energy or water use could result in financial penalties, reputational damage, and could jeopardise the fast-track planning status itself; (2) failing to deliver on the local job commitments could disengage the community and the council, generating bad publicity or withdrawal of planning support, and creating social inequity if the promised opportunities are not genuinely accessible to local people.', '1 mark per sustainability element correctly identified, up to 2. 1 mark per element correctly paired with a valid scenario-linked consideration, up to 2. 1 mark per valid impact of ignoring sustainability, up to 2. Cap 5.', NULL, true, NULL, 1, 14, 3);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('e289380d-6869-44e3-a643-f2b9dc3132d6', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q15', 'LO13', 'mock_exam', 'long_answer', false, false, 5, 'You are project manager opening a new 40-bed hospital ward. The team combines clinical staff transferring from other wards, newly hired band-5 nurses, and an estates project team who have never worked with clinical staff before. Two ward sisters and the estates lead will coordinate remotely from other sites for the first six weeks.

Explain (a) two characteristics of an effective team you would aim to build in this newly formed group, (b) one team-development model, other than Tuckman, you could use to understand how the group works together, and (c) one challenge created by the six-week period where three coordinators work remotely.', NULL, NULL, '(a) Two characteristics: clear roles and responsibilities aligned to each person''s skills and experience, so clinical staff work to clinical roles and estates staff to estates roles without overlap or gaps; and open, honest communication that builds trust across a group that has not worked together before, given the mix of transferring staff, new hires and estates staff. (b) Belbin: a model identifying nine preferred team roles that combine to produce an effective team, letting the leader recognise and use the strengths and behaviours already present in this mixed group rather than assuming everyone should work the same way. (c) One challenge: it is harder to build deep trust and to detect early signs of conflict when team members are working remotely, so the two ward sisters and the estates lead risk feeling disconnected from decisions being made by the co-located majority during those six weeks.', '1 mark per characteristic of an effective team correctly identified, up to 2. 1 mark for correctly naming a team-development model other than Tuckman. 1 mark for correctly describing what that model offers. 1 mark for a valid remote-working challenge linked to the scenario. Cap 5.', NULL, true, NULL, 1, 15, 3);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('032cc1ba-a1b5-4402-8574-94afe9c5bd63', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q16', 'LO20', 'mock_exam', 'long_answer', false, false, 5, 'You are project manager relocating a 300-person insurance claims department to a new office. The current office''s IT helpdesk, a business-as-usual (BAU) function, must keep operating throughout the move to support ongoing claims processing, and several helpdesk staff are also assigned part-time to your project.

Explain (a) what a Work Breakdown Structure is and how it would help you plan this relocation, and (b) two ways the ongoing BAU helpdesk activity could impact your project schedule.', NULL, NULL, '(a) A Work Breakdown Structure (WBS) is a hierarchical breakdown of the work needed to deliver the project''s products, with the lowest level being a work package. It would let me break the relocation into work packages — such as IT decommissioning, cabling, furniture move and go-live testing — and allocate resources, estimate and schedule each one, rather than treating the move as a single undifferentiated task. (b) Two impacts: (1) helpdesk staff who are part-time on my project may be pulled onto BAU support tickets when claims-processing issues spike, creating resource conflicts that delay tasks depending on them; (2) BAU equipment or systems the helpdesk needs to keep running, such as shared servers or phone lines, may be unavailable for project use at the same time, creating a scheduling dependency between BAU availability and project activities such as final cutover.', '1 mark for a correct definition of a WBS. 1 mark per BAU impact on schedule correctly identified, up to 2. 1 mark per impact correctly explained with scenario-linked reasoning, up to 2. Cap 5.', NULL, true, NULL, 1, 16, 3);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('b5755494-2cb1-478e-a460-5b8ace024a61', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q17', 'LO23', 'mock_exam', 'long_answer', false, false, 5, 'You are project manager on a customer-data migration to a new CRM platform. During testing, a data-mapping error is discovered that has already caused around 200 customer records to be duplicated in the new system. No one has yet formally logged it.

Explain (a) why this is an issue rather than a risk, (b) the stages of the issue management process you would follow, and (c) one reason governance matters in how this issue is handled.', NULL, NULL, '(a) A risk is an uncertain event that may or may not happen in the future; an issue is a problem that has already occurred or exists now and requires action to resolve. The duplicate records have already happened, so this must be managed through the issue process, not the risk process. (b) Log and analyse — record the issue in the issue register and prioritise it against success criteria, scope, time, cost and benefits; Escalate — raise it to the sponsor and, if needed, the governance board, given the potential impact on customer data integrity; Assign actions — give responsibility for fixing the duplication to whoever is best placed to resolve it, such as the data migration lead; Apply change control — if fixing the mapping error changes the baselined migration approach or timeline, route the fix through formal change control to update the plans. (c) One reason: governance sets clear escalation routes and thresholds so an issue affecting customer data integrity is guaranteed to reach the right decision-makers promptly, rather than being quietly fixed and under-reported, and it ensures consistent treatment and reporting so lessons are captured for future migrations.', '1 mark for correctly distinguishing issue from risk with reference to the scenario. 1 mark per issue management stage correctly named in a sensible order, up to 3 (any three of the four). 1 mark for a valid reason governance matters. Cap 5.', NULL, true, NULL, 1, 17, 3);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('d81b73a0-b50e-46b5-8942-4a9ccd72fba7', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q18', 'LO6', 'mock_exam', 'short_answer', false, false, 2, 'State two reasons why project activities might need to be re-planned following a review.', NULL, NULL, 'Any two of: planned scope is not achieving the requirements; project team morale and satisfaction is low; contractor or supplier performance is poor; committed costs and cashflow exceed forecasts; the risk profile has changed; stakeholder communication is ineffective; resource availability has changed.', '1 mark per valid, distinct re-planning reason, up to 2. Cap 2.', NULL, true, NULL, 1, 18, 3);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('c7d915d5-2a80-44d1-9633-1339d97b7502', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q19', 'LO7', 'mock_exam', 'short_answer', false, false, 2, 'State the three types of assurance activity used to give a governance board confidence in a project, and what each one confirms.', NULL, NULL, 'Any two of: Controls — the day-to-day management system (policies, procedures, standards) that confirms risk impact is being minimised by design. Compliance — regular monitoring and checks (such as audits or PMO reviews) that confirm controls are actually being used. Independent review — internal or external audit or peer review that gives a strategic overview of the whole system of control.', '1 mark per assurance activity type correctly named with what it confirms, up to 2. Cap 2.', NULL, true, NULL, 1, 19, 3);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('5bdfec1a-c6c8-40d8-8370-bd42b5a9e332', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q20', 'LO11', 'mock_exam', 'short_answer', false, false, 2, 'State two typical sources of conflict that can arise during the deployment phase of a project.', NULL, NULL, 'Any two of: resource availability and commitment issues; missed deadlines; project processes not being followed; supplier or contractor underperformance.', '1 mark per valid, distinct source of conflict correctly linked to the deployment phase, up to 2. Cap 2.', NULL, true, NULL, 1, 20, 3);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('4081014e-715f-423b-9d71-55feb02dc7e6', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q33', 'LO2', 'mock_exam', 'long_answer', false, false, 5, 'You are project manager at a mid-sized charity running its first-ever digital fundraising platform, funded by a one-off grant. The organisation has never run a formal project before — there are no agreed decision-making processes, and the trustee board has asked why "some proper structure" is needed when "everyone just wants to get on with the work."

Explain (a) two aspects of governance you would put in place and why each is required, and (b) why it matters that this project is explicitly linked to the charity''s strategic objectives.', NULL, NULL, '(a) Two aspects: Policies — a deliberate set of principles guiding how decisions get made, such as who can approve spend from the grant, because without agreed policies, decisions will be made inconsistently and disputes will arise about who had the authority to decide; and delegated responsibilities — using a tool such as a RACI to make roles explicit (who is responsible for content, who is accountable for grant spend, who must be consulted or informed), because in an organisation that has never run a formal project, ambiguity about ownership will otherwise slow every decision and create duplicated or dropped work. (b) It matters because projects exist to deliver strategic change; if this platform is not explicitly linked to the charity''s strategic objectives (for example, growing sustainable income), there is a risk of misallocating scarce grant-funded resource on work that does not address the charity''s actual priorities, of measuring performance against the wrong metrics, and of reputational risk if the platform''s execution contradicts the charity''s values or mission.', '1 mark per aspect of governance correctly named, up to 2. 1 mark per aspect correctly justified with a reason it is required, up to 2. 1 mark for a valid reason linking to strategic objectives matters. Cap 5.', NULL, true, NULL, 2, 13, 3);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('fd44bf0e-830d-4444-af65-48c86faf8be0', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q34', 'LO9', 'mock_exam', 'long_answer', false, false, 5, 'You are project manager on a local council''s smart-bin sensor rollout, expected to reduce collection costs and improve recycling rates. The council''s Head of Communications has asked how you will keep residents and refuse-collection crews engaged with the change, and how you will show councillors the rollout is delivering on the council''s published sustainability strategy.

Explain (a) one tool you would use to link the project''s benefits to the council''s strategic objectives, and (b) two appropriate methods for communicating benefits to residents and to councillors respectively, with a reason for each choice.', NULL, NULL, '(a) Benefits mapping: a visual tool linking the project''s outputs (sensor-fitted bins, route-optimisation software) to intermediate benefits (fewer unnecessary collections, better route efficiency) to end benefits (reduced collection costs, improved recycling rates) to the council''s strategic objective — its published sustainability strategy — making the cause-and-effect chain explicit for councillors and residents alike. (b) For residents: email, the council website or social media, appropriate for broad-reach awareness of a change affecting many households, though it risks being ignored if not paired with more visible communication. For councillors: a formal report at a scheduled council or committee meeting, appropriate for a governance audience that needs an evidence trail and the ability to scrutinise progress against the sustainability strategy before further investment decisions.', '1 mark for correctly naming benefits mapping (or another valid strategic-alignment tool) with a valid description. 1 mark per audience-appropriate communication method correctly identified, up to 2. 1 mark per method correctly justified with a reason it suits that audience, up to 2. Cap 5.', NULL, true, NULL, 2, 14, 3);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('ef6a6d9a-afc3-4500-bc13-fb5e5b0a03d5', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q35', 'LO14', 'mock_exam', 'long_answer', false, false, 5, 'You are project manager assembling a project team for a global product launch, recruiting from offices in the UK, India and the UAE. During shortlisting, a hiring manager comments that a strong candidate "might struggle to fit in" because of their age, and that another candidate''s visible religious dress "could be an issue with some clients."

Explain (a) two protected characteristics referenced in the hiring manager''s comments, and (b) the difference between conscious and unconscious bias, applying each to what has happened in this scenario.', NULL, NULL, '(a) Two protected characteristics: age (referenced in "might struggle to fit in... because of their age") and religion or belief (referenced in the comment about visible religious dress) — both are characteristics that, under frameworks such as the UK Equality Act, may cause a person to be treated less favourably if acted upon. (b) Conscious bias is deliberate prejudice or preference a person knows they hold and acts on; unconscious bias is involuntary prejudice, often from societal stereotype, that a person does not realise is shaping their judgement. If the hiring manager genuinely believes clients would react badly and knowingly factors that belief into the decision, that is conscious bias being acted on directly. If the manager is unaware that assumptions about age or religious dress are influencing their view of "fit," and would deny holding any bias, that is unconscious bias — it still needs active counter-measures, such as structured, objective selection criteria, even though the manager does not intend it.', '1 mark per protected characteristic correctly identified from the scenario, up to 2. 1 mark for a correct definition of conscious bias. 1 mark for a correct definition of unconscious bias. 1 mark for correctly applying at least one of the two definitions back to the scenario. Cap 5.', NULL, true, NULL, 2, 15, 3);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('d5578442-1520-4b47-9ec9-bc33b28fc164', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q36', 'LO16', 'mock_exam', 'long_answer', false, false, 5, 'You are project manager on a new ERP system for a mid-sized manufacturer. Eighty requirements have been gathered from production, finance, warehouse and sales stakeholders, ranging from "the system must record batch numbers for traceability" to "the system should feel modern and be pleasant to use."

Explain (a) the four-step requirements management process you would follow to take these eighty requirements from initial gathering to an agreed scope baseline, and (b) which of the two example requirements given is functional and which is non-functional, with a reason for each.', NULL, NULL, '(a) Gather — identify all relevant stakeholders (production, finance, warehouse, sales) and capture requirements through interviews, workshops, observation or document review, ensuring no stakeholder group is missed; Analysis — use a technique such as Function (Cost) Analysis to understand the value of each requirement, identify gaps and resolve conflicts between stakeholder groups, then feed findings back to stakeholders; Justifying requirements — prioritise using a technique such as MoSCoW and link priorities to benefit value, then report the justified priorities back to stakeholders; Baseline needs — set the agreed requirements baseline, from which the team determines deliverables, manages change formally, and guards against scope creep. (b) "The system must record batch numbers for traceability" is a functional requirement, because it describes a capability the system must provide. "The system should feel modern and be pleasant to use" is a non-functional requirement, because it describes a quality or performance characteristic — usability — rather than a specific function the system performs.', '1 mark per requirements-management step correctly named in a sensible sequence, up to 3 (any three of the four). 1 mark for correctly classifying the functional requirement with a reason. 1 mark for correctly classifying the non-functional requirement with a reason. Cap 5.', NULL, true, NULL, 2, 16, 3);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('450d2fdd-b73b-4f8f-a7bd-8ff9635a3f35', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q37', 'LO24', 'mock_exam', 'long_answer', false, false, 5, 'You are project manager on a marketing-automation platform build. The Head of Sales has emailed asking for a new integration with a lead-scoring tool to be added, giving a two-line description and no further detail, saying "just get it added, it''s important." You are five weeks from planned go-live.

Explain (a) three fields the change request should capture before it can be properly evaluated, and (b) two questions you would ask to justify a recommendation to approve, reject or defer this request.', NULL, NULL, '(a) Three fields: a clear description of the change — what the integration should actually do, beyond the two-line email; the reason for the change — why the lead-scoring integration is needed now, such as a sales driver or customer demand; and the areas impacted — a first-pass view of which parts of the platform build the integration would touch. A named change request owner, accountable for progressing it, should also be captured. (b) Two questions: (1) Does the project have the skills and resources to deliver this integration within the five weeks remaining, or would external support be needed? (2) Does the change affect the go-live date, and if so, are the outcomes still useful to the business at a later date, or does the five-week window make approval unrealistic without deferring either the integration or go-live itself?', '1 mark per change request field correctly identified, up to 3. 1 mark per valid justification question correctly linked to the scenario, up to 2. Cap 5.', NULL, true, NULL, 2, 17, 3);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('9fa06978-cad1-4129-8310-05c4072999a4', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q38', 'LO17', 'mock_exam', 'short_answer', false, false, 2, 'Besides MoSCoW, state two other techniques that could be used to prioritise requirements when developing a solution.', NULL, NULL, 'Any two of: investment appraisal (weighing cost against benefit and risk); numerical assignment (grouping requirements into numbered priority bands); the ABC model (classifying into three tiers of importance); the 5 Whys (questioning to uncover the underlying need behind a requirement); stakeholder commitment to a solution; market capability or supply availability.', '1 mark per valid, distinct prioritisation technique named, up to 2. Cap 2.', NULL, true, NULL, 2, 18, 3);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('b136becf-ffae-44d6-905f-0d74117d062c', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q39', 'LO21', 'mock_exam', 'short_answer', false, false, 2, 'State what each of the four letters in a RACI matrix stands for.', NULL, NULL, 'R = Responsible (does the work); A = Accountable (approves the work, held to account); C = Consulted (provides input, two-way dialogue); I = Informed (kept up to date, one-way communication).', '1 mark for correctly stating at least two of the four letters. 1 mark for correctly stating all four letters. Cap 2.', NULL, true, NULL, 2, 19, 3);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('b372ca86-3603-492b-b34a-4fa9e3e72e6d', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q40', 'LO18', 'mock_exam', 'short_answer', false, false, 2, 'State two of the elements a quality plan should define for each quality activity.', NULL, NULL, 'Any two of: Methods of verification (how quality will be checked, e.g. inspection, testing, audit); Resources (the people, equipment and tools needed); Frequency (how often the activity takes place); Pass/fail criteria (the standard against which the check is judged); Responsibility (who is accountable for carrying out the check).', '1 mark per valid, distinct quality plan element correctly named, up to 2. Cap 2.', NULL, true, NULL, 2, 20, 3);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('4ab2859f-c42a-4f9d-a59e-8a481036f638', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q13', 'LO6', 'mock_exam', 'long_answer', false, false, 5, 'You are project manager on a residential construction project. A recent site inspection found recurring plastering defects across twelve units. The site team has been mentioning "some issues" verbally in weekly calls for a month, but nothing has been formally reported, and the sponsor only learned the scale of the problem by chance during a site visit.

Explain (a) two categories of information that should have been produced and shared to inform decision-making earlier, and (b) one reason the project''s plans may now need to be re-planned as a result.', NULL, NULL, '(a) Two categories: status reporting — clear reporting of progress and quality position against the plan''s acceptance criteria, so the sponsor understands the cost, schedule and quality position rather than relying on informal comments in calls; and risk identification — formal identification and escalation of the emerging pattern of defects as a risk (or, once confirmed across twelve units, an issue), so corrective action or escalation happens while there is still time to act, rather than the sponsor discovering the scale by chance. (b) One reason: the planned scope is not achieving the required quality, so remediation work for twelve units needs to be added to the schedule and budget, and the baselined plan updated to reflect the additional rework and any knock-on delay to handover.', '1 mark per information category correctly identified, up to 2. 1 mark per category correctly explained with a reason it should have informed earlier decision-making, up to 2. 1 mark for a valid re-planning reason linked to the scenario. Cap 5.', NULL, true, NULL, 1, 13, 4);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('bbd69a6b-1881-44e0-9bcb-c2062cefa817', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q14', 'LO7', 'mock_exam', 'long_answer', false, false, 5, 'You are project manager on a government digital service replacing a paper-based benefits application process. The programme''s internal audit function has proposed a very heavy assurance schedule — weekly deep-dive reviews of every workstream, regardless of risk level — and delivery leads are pushing back, arguing it will slow the programme without adding value.

Explain three of the criteria an effective assurance plan should meet, and use them to explain what is wrong with the audit function''s current proposal.', NULL, NULL, 'An effective assurance plan should be: (1) Independent, objective and proportionate to the work — proportionate meaning the level of scrutiny should match the level of risk, not be applied at maximum intensity everywhere; the current proposal applies the same heavy weekly review to every workstream regardless of risk, which is disproportionate and will slow low-risk work for no benefit. (2) Targeted at the greatest risks — coverage should follow the risk register rather than being applied as a flat schedule; the proposal does not appear to differentiate by risk level at all. (3) Coordinated in its timing and cycles — reviews should land before key decision gates so findings can inform decisions, rather than running to a fixed weekly cadence disconnected from the programme''s actual decision points.', '1 mark per assurance-plan criterion correctly named, up to 3. 1 mark per criterion correctly applied to explain the flaw in the audit proposal, up to 3. Cap 5.', NULL, true, NULL, 1, 14, 4);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('1f647f24-2f5b-44df-8f13-3060dceae35f', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q15', 'LO11', 'mock_exam', 'long_answer', false, false, 5, 'You are project manager on a new product design team. Two designers strongly disagree about the direction of a key feature — one wants a simpler, faster-to-build version, the other believes it under-delivers on user needs and is willing to argue the point repeatedly in team meetings. The disagreement has slowed the last two design reviews, but it has also surfaced a usability risk neither designer had raised before.

Explain (a) one positive impact this conflict has already had on the project, and (b) two negative impacts the project risks if the conflict is not addressed.', NULL, NULL, '(a) One positive impact: the disagreement has surfaced a new usability risk that neither designer had previously raised — a direct benefit of open debate, since conflict can bring hidden risks to the surface that would otherwise stay hidden until later, when they would be more expensive to fix. (b) Two negative impacts: continued disagreement is diverting management time away from other design decisions as reviews keep stalling on this one issue; and if left unresolved, it risks lowering team morale and damaging the working relationship between the two designers, making them less willing to raise concerns openly with each other in future.', '1 mark for a valid positive impact of conflict correctly linked to the scenario. 1 mark for explaining why that positive impact matters (surfacing risk early). 1 mark per valid negative impact correctly linked to the scenario, up to 2. 1 mark for explaining why at least one negative impact matters, beyond simply naming it. Cap 5.', NULL, true, NULL, 1, 15, 4);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('f8f64286-786a-47e0-b218-000f3bffc486', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q16', 'LO15', 'mock_exam', 'long_answer', false, false, 5, 'You are project manager on a cloud-migration project for an asset-management firm, moving client portfolio data to a new hosting provider. During due diligence, you discover the hosting provider''s ISO 27001 information-security certificate appears to have been altered — the certification body''s logo and the accreditation number don''t match. The provider is a long-standing partner, and your sponsor is keen not to damage the relationship over "what might just be a formatting issue."

Explain (a) why you have a professional duty to act rather than let this pass, and (b) two sources of specialist advice you would consult before deciding how to proceed.', NULL, NULL, '(a) Professionals have a duty to "speak up" and report wrongdoing through an organisational process — this is treated as a professional obligation, not an optional courtesy, especially where the discrepancy touches information security for client financial data. Letting a potentially altered security certificate pass unchallenged because of relationship pressure from the sponsor would itself be a compliance and ethical failure, regardless of whether it later turns out to be innocent, and it needs formal escalation rather than an informal conversation. (b) Two sources: APM''s Code of Ethics and Professional Conduct, for guidance on personal conduct and the duty to raise concerns; and the organisation''s legal team or external lawyers, for advice on the compliance and contractual implications of a potentially falsified security certificate before any further client data is migrated.', '1 mark for correctly naming the professional duty to "speak up" or report wrongdoing. 1 mark for a valid explanation of why relationship pressure does not override that duty in this context. 1 mark for identifying that this needs formal escalation rather than an informal conversation. 1 mark per valid, distinct source of specialist advice correctly named, up to 2. Cap 5.', NULL, true, NULL, 1, 16, 4);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('643b2c83-2594-451b-a215-2f8162e2f9a0', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q17', 'LO17', 'mock_exam', 'long_answer', false, false, 5, 'You are project manager evaluating options for new imaging equipment for a hospital trust. Options include buying the equipment outright, leasing it, or entering a managed-service partnership with the manufacturer. The trust also needs to decide whether to roll the new equipment out to all six sites at once or phase it in gradually.

Explain (a) two criteria types you would use to evaluate the buy/lease/partnership options, with an example of what each considers, and (b) which transition approach — phased or "big bang" — you would recommend and why.', NULL, NULL, '(a) Two criteria types: Procurement — weighing lease vs buy vs make vs service vs partnership as live options, considering upfront cost against ongoing commitment and flexibility to upgrade equipment as imaging technology changes; and Management — considering the life cycle and governance implications of each option, since a managed-service partnership requires a different, ongoing governance relationship with the manufacturer than a simple purchase. (Technical — future-proofing against imaging technology changes — or Social criteria could also be credited if justified.) (b) A phased rollout across the six sites, because it lets lessons learned and any issues with the new equipment or workflow be identified and corrected at the first site or two before the trust commits to a full six-site rollout, reducing the risk of replicating a problem across every site simultaneously, which a "big bang" approach would risk.', '1 mark per criterion type correctly named, up to 2. 1 mark per criterion correctly paired with a scenario-relevant example, up to 2. 1 mark for a valid transition-approach recommendation with justification. Cap 5.', NULL, true, NULL, 1, 17, 4);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('330625b5-2cd9-485f-8b9e-b0727882dfb7', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q18', 'LO5', 'mock_exam', 'short_answer', false, false, 2, 'In the context of contract negotiation, state what BATNA and ZOPA each stand for, and briefly define one of them.', NULL, NULL, 'BATNA = Best Alternative to a Negotiated Agreement; ZOPA = Zone of Possible Agreement. BATNA is the most advantageous fallback course of action a party can take if the negotiation fails. ZOPA is the range within which an agreement is possible, based on the overlap between the buyer''s maximum and the seller''s minimum.', '1 mark for correctly expanding both acronyms. 1 mark for a correct definition of at least one of them. Cap 2.', NULL, true, NULL, 1, 18, 4);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('a781a7a2-2606-47b4-bbf2-c1ab168182a7', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q19', 'LO2', 'mock_exam', 'short_answer', false, false, 2, 'State two project governance roles, other than the Project Manager and Project Sponsor, and one responsibility of each.', NULL, NULL, 'Any two of: Project Steering Board/Group — provides strategic direction, authorises the business case, sanctions funding, decides on escalated issues. Product Owner — defines product scope, prioritises the backlog, and accepts delivered increments (in iterative or hybrid life cycles). Users — define requirements and acceptance criteria. Project Team — performs tasks and delivers outputs, reporting progress.', '1 mark per correctly named role with a valid responsibility, up to 2. Cap 2.', NULL, true, NULL, 1, 19, 4);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('81c760e2-dab0-4f6c-9a0c-25f600b713d3', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q20', 'LO9', 'mock_exam', 'short_answer', false, false, 2, 'State the difference between an "end benefit" and an "intermediate benefit," giving one example of each.', NULL, NULL, 'An end benefit aligns directly with a strategic objective and is often only confirmed months after project closure, for example a sustainable office that supports long-term growth. An intermediate benefit is realised during the project and supports the eventual achievement of the end benefit, useful for demonstrating progress before the end benefit can be confirmed, for example reduced energy bills or improved staff engagement along the way.', '1 mark for a correct distinction between end and intermediate benefit. 1 mark for a valid example of each. Cap 2.', NULL, true, NULL, 1, 20, 4);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('9e5934cb-ea66-410f-a685-dcfbafc66049', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q32', 'LO18', 'mock_exam', 'long_answer', false, false, 5, 'You are project manager on a customer-service transformation for a telecoms provider. The business case promises a 10-point improvement in Net Promoter Score (NPS) within twelve months of go-live. The programme board has asked how the quality plan will demonstrate this promise is actually being delivered, not just assumed.

Explain (a) why quality indicators need to be explicitly linked to the business case in this project, and (b) two elements the quality plan should define so the NPS promise can be properly tracked.', NULL, NULL, '(a) Quality indicators tie back to the business case so the project can prove it has delivered the value it promised. Without a measurable indicator tied to the NPS commitment, the programme board has no way of confirming whether the transformation actually improved customer experience, or whether any change in NPS is coincidental. Quality planning answers "what does good look like?", and here "good" is explicitly defined by the business case''s 10-point NPS target. (b) Two elements: methods of verification — how NPS will actually be measured, such as a defined post-interaction survey methodology applied consistently before and after go-live; and frequency — how often NPS will be measured and reported, such as monthly, so trend data, not a single snapshot, demonstrates progress towards the twelve-month target.', '1 mark for a valid explanation of why quality indicators must link to the business case. 1 mark for correctly linking this to the specific NPS promise in the scenario. 1 mark per quality plan element correctly identified and applied to NPS tracking, up to 3. Cap 5.', NULL, true, NULL, 2, 12, 4);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('38b0487d-209c-45b5-aaa6-6fe6bea7a9f3', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q33', 'LO19', 'mock_exam', 'long_answer', false, false, 5, 'You are project manager brought in six months into a £9m rail-depot upgrade that started without a single integrated project management plan — each function (engineering, safety, commercial) has been working from its own separate documents. Two disputes have already arisen between engineering and commercial about what was actually agreed on scope, and a new safety inspector joining next month will need to get up to speed quickly.

Explain (a) two problems this project has experienced as a direct result of not having an integrated PMP, and (b) two reasons producing one now would help, referencing the specific situations described.', NULL, NULL, '(a) Two problems: different team members have been working to different assumptions, since engineering, safety and commercial each hold separate documents rather than one source of truth — this is the direct cause of the disputes between engineering and commercial about what was agreed on scope; and there has been no baseline against which to measure progress or manage change, meaning scope disagreements cannot be resolved by referring back to an agreed position. (b) Two reasons: it would act as a single source of truth, so future disagreements between functions can be resolved by referring to one agreed document rather than each function''s separate version; and it would serve as induction material, letting the new safety inspector get up to speed from one integrated document covering scope, resources and management strategies, rather than being talked through three separate, potentially inconsistent sets of documentation.', '1 mark per problem correctly identified as resulting from the lack of an integrated PMP, up to 2. 1 mark per problem correctly linked to the specific dispute or onboarding situation in the scenario, up to 2. 1 mark for a valid additional reason producing the PMP now would help. Cap 5.', NULL, true, NULL, 2, 13, 4);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('e6b36542-994a-4e20-a75e-2aa60a703c84', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q34', 'LO21', 'mock_exam', 'long_answer', false, false, 5, 'You are project manager on a mobile app development project. Your organisation has a fixed team of six developers who cannot be increased — no budget for contractors and no other developers available internally. The current schedule shows three critical features all requiring development in the same two-week period.

Explain (a) which resource optimisation technique is appropriate given the fixed team size, and how it differs from the alternative, and (b) two practical actions you could take to apply it to this two-week clash.', NULL, NULL, '(a) Resource levelling is appropriate, because the resource pool of six developers is fixed and cannot flex, so the schedule must be adjusted to fit the available resource rather than the other way round — levelling answers "with the resources available, when will the work be finished?" This differs from resource smoothing, which keeps the end date fixed and instead adjusts resource demand within available float (for example, adding people or parallelising tasks); smoothing is not viable here because there is no ability to add developers, and the schedule end date may need to move as a result of levelling. (b) Two actions: redefine or extend the duration of one or more of the three features so they no longer all require full development effort in the same two-week window, sequencing them where dependencies allow; and reprioritise which of the three features is genuinely critical, using requirements priority such as Must-haves, so the team''s fixed capacity is applied to the highest-value feature first and lower-priority features shift later in the schedule.', '1 mark for correctly naming resource levelling with a valid reason linked to the fixed team size. 1 mark for correctly distinguishing levelling from smoothing. 1 mark for correctly noting the schedule end date may need to move as a result. 1 mark per practical levelling action correctly described, up to 2. Cap 5.', NULL, true, NULL, 2, 14, 4);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('caceb76a-55ba-4f54-95d6-3337e74eb8f8', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q35', 'LO4', 'mock_exam', 'long_answer', false, false, 5, 'You are project manager on a £5m factory-automation business case for a manufacturer. Since approval three months ago, a major competitor has launched a cheaper automated product line, and a new energy-efficiency grant has become available that could offset some of the project''s cost.

Explain (a) three of the five elements of a business case, describing what each would need to reflect given this new information, and (b) why the business case should be reviewed now rather than left until the next scheduled decision gate.', NULL, NULL, '(a) Strategic context — needs to reflect the shifted competitive landscape now that a cheaper rival product exists, and whether the automation project still delivers the intended competitive advantage. Economic analysis — the return-on-investment appraisal should be revisited, since the new energy-efficiency grant changes the cost side of the appraisal and could improve the case''s value for money. Financial case — affordability and funding source should be updated to reflect potential grant income, which may free up budget or shorten payback. (b) The business case is a living document that should be reviewed whenever significant change occurs, not only at scheduled gates. Both the competitor launch and the new grant are material changes that affect whether the benefits and costs originally approved are still accurate, and waiting until the next scheduled gate risks the project continuing on assumptions that are no longer valid — the grant might reduce cost now, or the competitive threat might require a scope change sooner than the next gate allows.', '1 mark per business case element correctly named, up to 3. 1 mark per element correctly applied to the competitor or grant information, up to 3. 1 mark for a valid reason to review now rather than waiting for the next gate. Cap 5.', NULL, true, NULL, 2, 15, 4);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('00fa1d28-a5e7-4a22-9553-d73bae5466c7', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q36', 'LO12', 'mock_exam', 'long_answer', false, false, 5, 'You are project manager on a highway resurfacing programme. A recently qualified graduate engineer seems increasingly disengaged — missing minor deadlines and contributing less in meetings — despite being paid fairly and having good working conditions. Separately, an experienced site foreman who has delivered strong results for fifteen years has started pushing back on being told exactly how to sequence tasks, saying he "just needs the outcome, not step-by-step instructions."

Explain (a) which motivation model best explains why good pay and conditions alone have not kept the graduate engineer engaged, and what it suggests you do next, and (b) how you would adapt your leadership style differently for the graduate engineer versus the site foreman, and why.', NULL, NULL, '(a) Herzberg''s Two-Factor Theory: pay and working conditions are hygiene factors — they prevent dissatisfaction but do not by themselves create motivation. The engineer''s disengagement suggests the missing ingredients are motivators, such as recognition, achievement, responsibility or growth; the next step is to identify which motivator is missing (for example, a lack of recognition for work done, or no clear development path) and address it directly, rather than assuming pay and conditions are sufficient. (b) For the graduate engineer: a more coaching-oriented, supportive style, giving personalised guidance and feedback to rebuild engagement and help them develop capability and confidence, since disengagement in a new starter often follows unmet motivator needs rather than unwillingness to work. For the site foreman: a more delegative style, giving him the outcome and stepping back on the how, since he is an established, high-performing team member who — per McGregor''s Theory Y — is self-motivated and takes pride in ownership; continuing to direct his tasks closely would demotivate rather than support him.', '1 mark for correctly naming Herzberg''s Two-Factor Theory. 1 mark for correctly distinguishing hygiene factors from motivators and applying this to the engineer. 1 mark for a valid coaching-style recommendation for the graduate engineer with reason. 1 mark for a valid delegative-style recommendation for the site foreman with reason. 1 mark for correctly referencing Theory Y (or an equivalent correct justification) for the foreman. Cap 5.', NULL, true, NULL, 2, 16, 4);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('de83c0f1-fb8e-400c-b4a3-9fc526c5ff5e', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q37', 'LO14', 'mock_exam', 'short_answer', false, false, 2, 'State two reasonable adjustments a project manager could make to help team members with different needs contribute fully.', NULL, NULL, 'Any two of: providing assistive technology or software for a team member with a visual or hearing impairment; adjusting meeting format or providing materials in advance for a neurodivergent team member; offering a quiet workspace or flexible break patterns for someone managing a health condition; translating key materials or providing an interpreter for a team member whose first language differs from the working language.', '1 mark per valid, distinct reasonable adjustment, up to 2. Cap 2.', NULL, true, NULL, 2, 17, 4);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('b0a638a0-5141-426b-b8d2-2d0dea5149e1', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q38', 'LO24', 'mock_exam', 'short_answer', false, false, 2, 'State two things that could go wrong if project plans are not updated after a change has been approved.', NULL, NULL, 'Any two of: the team works from outdated information, wasting time and money; conflict and disengagement follow as people work to different versions; delivered outputs may end up redundant; stakeholders lose confidence in the project; other projects or business-as-usual work are adversely affected; the business case''s benefits may not be realised.', '1 mark per valid, distinct consequence, up to 2. Cap 2.', NULL, true, NULL, 2, 18, 4);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('0c6e4036-ffe4-42d8-adec-568b13a4954f', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q39', 'LO13', 'mock_exam', 'short_answer', false, false, 2, 'State two characteristics of an effective project team.', NULL, NULL, 'Any two of: clear roles and responsibilities aligned to skills and experience; a shared sense of accountability; open and honest communication; mutual trust and respect; a common sense of purpose or shared objectives; appreciation of the diverse strengths each member brings.', '1 mark per valid, distinct characteristic of an effective team, up to 2. Cap 2.', NULL, true, NULL, 2, 19, 4);
insert into public.questions (id, course_id, external_id, learning_objective, context, question_type, is_scenario, is_case_study, marks, prompt, options, correct_answer, model_answer, marking_guide, explanation, mock_suitable, section_id, part, position, exam_set) values ('38ee4b42-32c4-4026-8b13-225fccadb568', '3b6e12c0-321f-41b2-8536-db39f5678301', 'Q40', 'LO16', 'mock_exam', 'short_answer', false, false, 2, 'State the four steps of the requirements management process, in order.', NULL, NULL, 'Gather (identify stakeholders and capture requirements); Analysis (use a technique such as Function Cost Analysis to understand value, resolve conflicts, and feed back to stakeholders); Justifying requirements (prioritise, e.g. using MoSCoW, and report priorities back to stakeholders); Baseline needs (set the agreed requirements baseline for managing scope and change).', '1 mark for naming at least two of the four steps correctly. 1 mark for naming all four steps correctly, roughly in order. Cap 2.', NULL, true, NULL, 2, 20, 4);

commit;